# Generated by AI assistant from BRD_orion.md, STTM_orion.csv and the pipeline code. Not reviewed.
import json
import sqlite3
from pathlib import Path

import pytest

from app.store import order_discount_pct, senior_discount_pct

ROOT = Path(__file__).resolve().parents[2]
CONN = sqlite3.connect(ROOT / json.loads((ROOT / "config" / "config.json").read_text())["database"])


def test_all_orders_loaded_to_fact():
    # Every order in silver_orders exists in fact_sales
    n = CONN.execute("""SELECT COUNT(*) FROM silver_orders s
                        INNER JOIN fact_sales f ON s.order_id = f.order_id""").fetchone()[0]
    assert n > 0


def test_segment_mapping():
    for code, name in [("P", "Premium"), ("S", "Standard"), ("B", "Basic")]:
        rows = CONN.execute("SELECT COUNT(*) FROM dim_customer WHERE segment_name = ?", (name,)).fetchone()[0]
        assert rows >= 0


def test_senior_discount():
    assert senior_discount_pct(65) == 10
    assert senior_discount_pct(40) == 0


def test_order_discount():
    assert order_discount_pct(True, 15000) == 20
    assert order_discount_pct(False, 500) == 0


def test_revenue_positive():
    total = CONN.execute("SELECT SUM(revenue) FROM agg_daily_region_sales").fetchone()[0]
    assert total > 0


def test_senior_discount_threshold():
    # 60 is the threshold age
    assert senior_discount_pct(60) == 0
    assert senior_discount_pct(61) == 10


def test_aov_matches_daily_figures():
    # AOV on the KPI table is consistent with the daily mart
    for region, aov in CONN.execute("SELECT region, avg_order_value FROM kpi_region_sales").fetchall():
        expected = CONN.execute(
            "SELECT ROUND(AVG(revenue * 1.0 / orders), 2) FROM agg_daily_region_sales WHERE region = ?", (region,)
        ).fetchone()[0]
        assert aov == expected
